from pysat.solvers import Glucose4

n = 7

def var(i, j, v):
    return i * n * n + j * n + v + 1

clauses = []

# Exactly one value per cell
for i in range(n):
    for j in range(n):
        clauses.append([var(i, j, v) for v in range(n)])
        for v1 in range(n):
            for v2 in range(v1 + 1, n):
                clauses.append([-var(i, j, v1), -var(i, j, v2)])

# Latin square: rows
for i in range(n):
    for v in range(n):
        clauses.append([var(i, j, v) for j in range(n)])
        for j1 in range(n):
            for j2 in range(j1 + 1, n):
                clauses.append([-var(i, j1, v), -var(i, j2, v)])

# Latin square: columns
for j in range(n):
    for v in range(n):
        clauses.append([var(i, j, v) for i in range(n)])
        for i1 in range(n):
            for i2 in range(i1 + 1, n):
                clauses.append([-var(i1, j, v), -var(i2, j, v)])

# Idempotent
for i in range(n):
    clauses.append([var(i, i, i)])

# QG3: x[i][j] = v1 and x[j][i] = v2 => x[v1][v2] = i
for i in range(n):
    for j in range(n):
        for v1 in range(n):
            for v2 in range(n):
                clauses.append([-var(i, j, v1), -var(j, i, v2), var(v1, v2, i)])

solver = Glucose4()
for clause in clauses:
    solver.add_clause(clause)

if solver.solve():
    model = solver.get_model()
    res = []
    for i in range(n):
        for j in range(n):
            for v in range(n):
                if model[var(i, j, v) - 1] > 0:
                    res.append(v)
    print(res)
else:
    print("UNSAT")

